Problem:
An electronics company makes economical and premium mobile phones in a factory that is divided into a hardware and software section. The hardware section must work 5 hours on each economical mobile phone but 12 hours on each premium one. The software section must work 3 hours for each mobile phone. The profit from the economical mobile phone is $150 and the profit from the premium mobile phone is $400. Due to a recent strike, the hardware section only has 150 hours available per week and the software section only has 100 hours available per week. How many of each phone should the company produce to maximize profit?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "economical phones",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "premium phones",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "economical phones",
     "coef": 150.0
    },
    {
     "var": "premium phones",
     "coef": 400.0
    }
   ]
  },
  "constraints": [
   {
    "name": "hardware hours",
    "terms": [
     {
      "var": "economical phones",
      "coef": 5.0
     },
     {
      "var": "premium phones",
      "coef": 12.0
     }
    ],
    "sense": "<=",
    "rhs": 150.0
   },
   {
    "name": "software hours",
    "terms": [
     {
      "var": "economical phones",
      "coef": 3.0
     },
     {
      "var": "premium phones",
      "coef": 3.0
     }
    ],
    "sense": "<=",
    "rhs": 100.0
   }
  ]
 },
 "facts": {
  "objective": 4950.0,
  "values": {
   "economical phones": 1.0,
   "premium phones": 12.0
  },
  "binding": [],
  "slack": {
   "hardware hours": 1.0,
   "software hours": 61.0
  },
  "shadow_prices": null,
  "limits": {
   "hardware hours": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "software hours": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
